sys_script.script:
(function executeRule(current, previous) {

    // Run only when Interview Result changes to Pass
    if (!current.result.changesTo('pass')) {
        return;
    }

    // 1. Get Application from Interview
    var application = current.application.getRefRecord();

    if (!application || !application.isValidRecord()) {
        gs.error('Offer Letter: Application not found.');
        return;
    }

    // 2. Get Student from Application
    var student = application.student.getRefRecord();

    if (!student || !student.isValidRecord()) {
        gs.error('Offer Letter: Student not found.');
        return;
    }

    // 3. Get Placement Drive from Application
    var drive = application.drive.getRefRecord();

    if (!drive || !drive.isValidRecord()) {
        gs.error('Offer Letter: Placement Drive not found.');
        return;
    }

    // 4. Get Company from Placement Drive
    var company = drive.company.getRefRecord();

    if (!company || !company.isValidRecord()) {
        gs.error('Offer Letter: Company not found.');
        return;
    }

    // 5. Prevent duplicate Offer Letter
    var existingOffer = new GlideRecord('x_snc_college_pl_0_offer_letter');

    existingOffer.addQuery(
        'application',
        application.getUniqueValue()
    );

    existingOffer.query();

    if (existingOffer.next()) {

        gs.info(
            'Offer Letter already exists for Application: ' +
            application.getDisplayValue()
        );

        return;
    }

    // 6. Create Offer Letter
    var offer = new GlideRecord('x_snc_college_pl_0_offer_letter');

    offer.initialize();

    offer.application = application.getUniqueValue();
    offer.student = student.getUniqueValue();
    offer.company = company.getUniqueValue();
    offer.job_role = drive.getValue('job_role');
    offer.package = drive.getValue('package');
    offer.offer_date = new GlideDateTime();

    var offerSysId = offer.insert();

    if (!offerSysId) {
        gs.error('Offer Letter creation failed.');
        return;
    }

    gs.info(
        'Offer Letter created successfully: ' +
        offer.getDisplayValue()
    );

    // 7. Create Student Notification
    var notification = new GlideRecord('x_snc_college_pl_0_student_notification');

    notification.initialize();

    notification.student = student.getUniqueValue();
    notification.application = application.getUniqueValue();
    notification.offer_letter = offerSysId;
    notification.title = 'Congratulations!';

    notification.message =
        'You have been selected for the ' +
        drive.getValue('job_role') +
        ' position at ' +
        company.getDisplayValue() +
        '. Please visit the Offer Letters section to view your offer details.';

    var notificationSysId = notification.insert();

    if (notificationSysId) {
        gs.info(
            'Student Notification created successfully: ' +
            notificationSysId
        );
    } else {
        gs.error(
            'Student Notification creation failed.'
        );
    }

})(current, previous);
